import { describeWaveform } from "@siren-ui/core/accessibility";
import {
  bucketSamples,
  deriveVisibleBucketCount,
  normalizeAmplitude,
} from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { memo, useMemo, useState } from "react";
import {
  PixelRatio,
  StyleSheet,
  View,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from "react-native";

export type WaveformProps = {
  samples: readonly number[];
  progress?: number;
  height?: number;
  barWidth?: number;
  gap?: number;
  maximumDensity?: number;
  color?: string;
  playedColor?: string;
  accessibilityLabel?: string;
  durationMs?: number;
  reducedMotion?: boolean;
  style?: StyleProp<ViewStyle>;
  barStyle?: StyleProp<ViewStyle>;
  onLayout?: (event: LayoutChangeEvent) => void;
};

export const Waveform = memo(function Waveform({
  samples,
  progress = 0,
  height = 48,
  barWidth = 3,
  gap = 2,
  maximumDensity = 240,
  color = "#8B929E",
  playedColor = "#266EF1",
  accessibilityLabel,
  durationMs,
  style,
  barStyle,
  onLayout,
}: WaveformProps) {
  const [width, setWidth] = useState(0);
  developmentWarning(
    "waveform-height",
    height >= 24,
    "Waveform heights below 24 points can be difficult to perceive.",
  );
  const safeProgress = normalizeAmplitude(progress);
  const visible = useMemo(() => {
    const count = deriveVisibleBucketCount({
      width,
      barWidth,
      gap,
      maximumDensity,
      pixelRatio: PixelRatio.get(),
    });
    return bucketSamples(samples, count);
  }, [barWidth, gap, maximumDensity, samples, width]);

  const handleLayout = (event: LayoutChangeEvent) => {
    setWidth(event.nativeEvent.layout.width);
    onLayout?.(event);
  };

  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={
        accessibilityLabel ??
        describeWaveform({ durationMs, progress: safeProgress })
      }
      onLayout={handleLayout}
      style={[styles.root, { height, gap }, style]}
    >
      {visible.map((sample, index) => {
        const played =
          visible.length < 2
            ? safeProgress > 0
            : index / (visible.length - 1) <= safeProgress;
        return (
          <View
            key={index}
            accessible={false}
            style={[
              styles.bar,
              {
                width: barWidth,
                height: Math.max(2, sample * height),
                backgroundColor: played ? playedColor : color,
              },
              barStyle,
            ]}
          />
        );
      })}
    </View>
  );
});

const styles = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", overflow: "hidden" },
  bar: { borderRadius: 999 },
});

import { normalizeAmplitude } from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { memo, useEffect } from "react";
import { StyleSheet, View, type StyleProp, type ViewStyle } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  type SharedValue,
} from "react-native-reanimated";

export type LiveWaveformProps = {
  sample: number;
  historySize?: number;
  paused?: boolean;
  direction?: "left-to-right" | "right-to-left";
  height?: number;
  color?: string;
  reducedMotion?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

function LiveBar({
  values,
  index,
  height,
  color,
  reducedMotion,
}: {
  values: SharedValue<number[]>;
  index: number;
  height: number;
  color: string;
  reducedMotion: boolean;
}) {
  const animatedStyle = useAnimatedStyle(() => {
    const value = values.value[index] ?? 0.04;
    return {
      transform: [{ scaleY: reducedMotion ? 0.35 : Math.max(0.04, value) }],
    };
  }, [height, index, reducedMotion]);
  return (
    <Animated.View
      style={[styles.bar, { height, backgroundColor: color }, animatedStyle]}
    />
  );
}

export const LiveWaveform = memo(function LiveWaveform({
  sample,
  historySize = 48,
  paused = false,
  direction = "left-to-right",
  height = 48,
  color = "#266EF1",
  reducedMotion = false,
  accessibilityLabel = "Live microphone level",
  style,
}: LiveWaveformProps) {
  const safeSize = Math.max(4, Math.min(160, Math.floor(historySize)));
  const values = useSharedValue(new Array<number>(safeSize).fill(0.04));
  developmentWarning(
    "live-history",
    historySize <= 160,
    "LiveWaveform history is capped at 160 samples to keep work bounded.",
  );

  useEffect(() => {
    if (paused) return;
    const next = values.value.slice(1);
    next.push(normalizeAmplitude(sample));
    values.value = next;
  }, [paused, sample, values]);

  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={accessibilityLabel}
      accessibilityState={{ disabled: paused }}
      style={[
        styles.root,
        direction === "right-to-left" && styles.reverse,
        { height },
        style,
      ]}
    >
      {Array.from({ length: safeSize }, (_, index) => (
        <LiveBar
          key={index}
          values={values}
          index={index}
          height={height}
          color={color}
          reducedMotion={reducedMotion}
        />
      ))}
    </View>
  );
});

const styles = StyleSheet.create({
  root: {
    flexDirection: "row",
    alignItems: "center",
    gap: 2,
    overflow: "hidden",
  },
  reverse: { flexDirection: "row-reverse" },
  bar: { flex: 1, minWidth: 1, borderRadius: 999 },
});

import {
  decibelsToAmplitude,
  normalizeAmplitude,
} from "@siren-ui/core/waveform";
import { useCallback } from "react";
import type { SharedValue } from "react-native-reanimated";

export function appendLiveSample(
  buffer: SharedValue<number[]>,
  sample: number,
  historySize: number,
): void {
  "worklet";
  const next = buffer.value.slice(
    Math.max(0, buffer.value.length - historySize + 1),
  );
  next.push(normalizeAmplitude(sample));
  buffer.value = next;
}

export function useExpoMeteringSample(onSample: (sample: number) => void) {
  return useCallback(
    (meteringDb: number | undefined) => {
      if (meteringDb !== undefined) onSample(decibelsToAmplitude(meteringDb));
    },
    [onSample],
  );
}

import { adjustableStep } from "@siren-ui/core/accessibility";
import { normalizeAmplitude } from "@siren-ui/core/waveform";
import { developmentWarning } from "@siren-ui/core/warnings";
import { useMemo, useRef, useState } from "react";
import {
  I18nManager,
  StyleSheet,
  View,
  type AccessibilityActionEvent,
  type LayoutChangeEvent,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import { Waveform } from "./waveform";

export type WaveformScrubberProps = {
  samples: readonly number[];
  positionMs: number;
  durationMs: number;
  onSeekPreview?: (positionMs: number) => void;
  onSeek: (positionMs: number) => void;
  height?: number;
  disabled?: boolean;
  reducedMotion?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function WaveformScrubber({
  samples,
  positionMs,
  durationMs,
  onSeekPreview,
  onSeek,
  height = 52,
  disabled = false,
  reducedMotion,
  accessibilityLabel = "Audio position",
  style,
}: WaveformScrubberProps) {
  const width = useRef(1);
  const lastPreviewAt = useRef(0);
  const [previewMs, setPreviewMs] = useState<number>();
  developmentWarning(
    "scrubber-height",
    height >= 44,
    "WaveformScrubber should be at least 44 points tall for a safe touch target.",
  );

  const toPosition = (x: number) => {
    const ratio = normalizeAmplitude(x / width.current);
    return (I18nManager.isRTL ? 1 - ratio : ratio) * Math.max(0, durationMs);
  };

  const gesture = useMemo(
    () =>
      Gesture.Race(
        Gesture.Pan()
          .enabled(!disabled)
          .runOnJS(true)
          .onUpdate(({ x }) => {
            const next = toPosition(x);
            setPreviewMs(next);
            const now = Date.now();
            if (now - lastPreviewAt.current >= 100) {
              lastPreviewAt.current = now;
              onSeekPreview?.(next);
            }
          })
          .onEnd(({ x }) => {
            const next = toPosition(x);
            setPreviewMs(undefined);
            onSeek(next);
          })
          .onFinalize(() => setPreviewMs(undefined)),
        Gesture.Tap()
          .enabled(!disabled)
          .runOnJS(true)
          .onEnd(({ x }) => onSeek(toPosition(x))),
      ),
    [disabled, durationMs, onSeek, onSeekPreview],
  );

  const onAccessibilityAction = (event: AccessibilityActionEvent) => {
    if (
      event.nativeEvent.actionName !== "increment" &&
      event.nativeEvent.actionName !== "decrement"
    )
      return;
    onSeek(
      adjustableStep(positionMs, durationMs, event.nativeEvent.actionName),
    );
  };

  const onLayout = (event: LayoutChangeEvent) => {
    width.current = Math.max(1, event.nativeEvent.layout.width);
  };
  const shownPosition = previewMs ?? positionMs;

  return (
    <GestureDetector gesture={gesture}>
      <View
        accessible
        accessibilityRole="adjustable"
        accessibilityLabel={accessibilityLabel}
        accessibilityValue={{
          min: 0,
          max: Math.max(0, Math.round(durationMs)),
          now: Math.round(shownPosition),
          text: `${Math.round(shownPosition / 1000)} seconds`,
        }}
        accessibilityActions={[
          { name: "increment", label: "Seek forward" },
          { name: "decrement", label: "Seek backward" },
        ]}
        onAccessibilityAction={onAccessibilityAction}
        onLayout={onLayout}
        style={[styles.touchArea, { minHeight: height }, style]}
      >
        <Waveform
          samples={samples}
          progress={durationMs > 0 ? shownPosition / durationMs : 0}
          height={Math.max(24, height - 12)}
          reducedMotion={reducedMotion}
        />
      </View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  touchArea: { justifyContent: "center", width: "100%" },
});

import { developmentWarning } from "@siren-ui/core/warnings";
import * as Haptics from "expo-haptics";
import { useMemo } from "react";
import {
  I18nManager,
  Pressable,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";

export type HoldToRecordProps = {
  active: boolean;
  locked?: boolean;
  disabled?: boolean;
  cancelThreshold?: number;
  lockThreshold?: number;
  holdDelayMs?: number;
  onStart: () => void;
  onCancel: () => void;
  onLock: () => void;
  onRelease: () => void;
  label?: string;
  cancelLabel?: string;
  lockLabel?: string;
  style?: StyleProp<ViewStyle>;
};

export function HoldToRecord({
  active,
  locked = false,
  disabled = false,
  cancelThreshold = 88,
  lockThreshold = 72,
  holdDelayMs = 180,
  onStart,
  onCancel,
  onLock,
  onRelease,
  label = "Hold to record",
  cancelLabel = "Cancel recording",
  lockLabel = "Lock recording",
  style,
}: HoldToRecordProps) {
  developmentWarning(
    "hold-target",
    cancelThreshold >= 64 && lockThreshold >= 56,
    "Hold gesture thresholds may be too small to avoid accidental actions.",
  );
  let cancelled = false;
  let didLock = false;
  const gesture = useMemo(
    () =>
      Gesture.Pan()
        .enabled(!disabled && !locked)
        .activateAfterLongPress(holdDelayMs)
        .runOnJS(true)
        .onBegin(() => {
          cancelled = false;
          didLock = false;
          void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
          onStart();
        })
        .onUpdate(({ translationX, translationY }) => {
          const cancelDistance = I18nManager.isRTL
            ? translationX
            : -translationX;
          if (!cancelled && cancelDistance >= cancelThreshold) {
            cancelled = true;
            void Haptics.notificationAsync(
              Haptics.NotificationFeedbackType.Warning,
            );
            onCancel();
          } else if (!didLock && -translationY >= lockThreshold) {
            didLock = true;
            void Haptics.selectionAsync();
            onLock();
          }
        })
        .onEnd(() => {
          if (!cancelled && !didLock) onRelease();
        }),
    [
      cancelThreshold,
      disabled,
      holdDelayMs,
      lockThreshold,
      locked,
      onCancel,
      onLock,
      onRelease,
      onStart,
    ],
  );

  return (
    <View style={[styles.container, style]}>
      <GestureDetector gesture={gesture}>
        <Pressable
          accessibilityRole="button"
          accessibilityLabel={label}
          accessibilityHint="Double tap to start recording, or press and hold then slide left to cancel or up to lock"
          accessibilityState={{ disabled, selected: active }}
          disabled={disabled}
          onPress={active ? onRelease : onStart}
          style={({ pressed }) => [
            styles.record,
            active && styles.active,
            pressed && styles.pressed,
          ]}
        >
          <View style={styles.recordGlyph} />
          <Text style={styles.label}>{active ? "Release to stop" : label}</Text>
        </Pressable>
      </GestureDetector>
      {active ? (
        <View style={styles.alternatives}>
          <Pressable
            accessibilityRole="button"
            accessibilityLabel={cancelLabel}
            onPress={onCancel}
            style={styles.action}
          >
            <Text>{cancelLabel}</Text>
          </Pressable>
          {!locked ? (
            <Pressable
              accessibilityRole="button"
              accessibilityLabel={lockLabel}
              onPress={onLock}
              style={styles.action}
            >
              <Text>{lockLabel}</Text>
            </Pressable>
          ) : null}
        </View>
      ) : null}
    </View>
  );
}

const styles = StyleSheet.create({
  container: { gap: 10 },
  record: {
    minHeight: 52,
    minWidth: 160,
    paddingHorizontal: 18,
    borderRadius: 18,
    backgroundColor: "#ECEEF2",
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 10,
  },
  active: { backgroundColor: "#FFE5E7" },
  pressed: { opacity: 0.7 },
  recordGlyph: {
    width: 14,
    height: 14,
    borderRadius: 7,
    backgroundColor: "#D92D3A",
  },
  label: { color: "#15171A", fontSize: 16, fontWeight: "600" },
  alternatives: { flexDirection: "row", gap: 8, justifyContent: "center" },
  action: {
    minHeight: 44,
    paddingHorizontal: 14,
    justifyContent: "center",
    borderRadius: 12,
    borderWidth: StyleSheet.hairlineWidth,
    borderColor: "#8B929E",
  },
});

import { formatDuration } from "@siren-ui/core/time";
import { memo } from "react";
import {
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from "react-native";

export type RecordingTimerProps = {
  durationMs: number;
  state: "recording" | "paused" | "processing";
  warningThresholdMs?: number;
  maximumDurationMs?: number;
  style?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
};

export const RecordingTimer = memo(function RecordingTimer({
  durationMs,
  state,
  warningThresholdMs,
  maximumDurationMs,
  style,
  textStyle,
}: RecordingTimerProps) {
  const warning =
    warningThresholdMs !== undefined && durationMs >= warningThresholdMs;
  const current = formatDuration(durationMs);
  const maximum =
    maximumDurationMs === undefined
      ? undefined
      : formatDuration(maximumDurationMs);
  const stateLabel =
    state === "recording"
      ? "Recording"
      : state === "paused"
        ? "Recording paused"
        : "Processing recording";
  return (
    <View
      accessible
      accessibilityRole="timer"
      accessibilityLabel={`${stateLabel}, ${current}${maximum ? ` of ${maximum}` : ""}`}
      accessibilityLiveRegion="polite"
      style={[styles.root, style]}
    >
      <Text style={[styles.time, warning && styles.warning, textStyle]}>
        {current}
        {maximum ? ` / ${maximum}` : ""}
      </Text>
      <Text style={styles.state}>{stateLabel}</Text>
    </View>
  );
});

const styles = StyleSheet.create({
  root: { alignItems: "center", gap: 3 },
  time: {
    color: "#15171A",
    fontSize: 20,
    fontVariant: ["tabular-nums"],
    fontWeight: "600",
  },
  warning: { color: "#A12A34" },
  state: { color: "#5D6470", fontSize: 13 },
});

import type { ReactNode } from "react";
import {
  Platform,
  Pressable,
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";
import {
  useAudioPermission,
  type AudioPermissionState,
} from "../hooks/use-audio-permission";

export type AudioPermissionGateRenderState = {
  state: AudioPermissionState;
  request: () => Promise<AudioPermissionState>;
  openSettings: () => Promise<void>;
};

export type AudioPermissionGateProps = {
  children: ReactNode | ((state: AudioPermissionGateRenderState) => ReactNode);
  renderFallback?: (state: AudioPermissionGateRenderState) => ReactNode;
  labels?: Partial<
    Record<"request" | "denied" | "blocked" | "settings", string>
  >;
  style?: StyleProp<ViewStyle>;
};

export function AudioPermissionGate({
  children,
  renderFallback,
  labels,
  style,
}: AudioPermissionGateProps) {
  const permission = useAudioPermission();
  const state: AudioPermissionGateRenderState = {
    state: permission.state,
    request: permission.request,
    openSettings: permission.openSettings,
  };
  if (permission.state === "granted")
    return <>{typeof children === "function" ? children(state) : children}</>;
  if (renderFallback) return <>{renderFallback(state)}</>;
  const blockedCopy = Platform.select({
    ios: "Enable microphone access in Settings to record audio.",
    android: "Allow microphone access in system settings to record audio.",
    default: "Microphone access is blocked.",
  });
  return (
    <View accessible accessibilityRole="summary" style={[styles.root, style]}>
      <Text style={styles.title}>
        {permission.state === "blocked"
          ? (labels?.blocked ?? blockedCopy)
          : (labels?.denied ?? "Microphone access is needed to record audio.")}
      </Text>
      {permission.state === "blocked" ? (
        <Pressable
          accessibilityRole="button"
          onPress={() => void permission.openSettings()}
          style={styles.button}
        >
          <Text style={styles.buttonLabel}>
            {labels?.settings ?? "Open settings"}
          </Text>
        </Pressable>
      ) : permission.state === "unknown" ? (
        <Text style={styles.detail}>Checking microphone access…</Text>
      ) : (
        <Pressable
          accessibilityRole="button"
          onPress={() => void permission.request()}
          style={styles.button}
        >
          <Text style={styles.buttonLabel}>
            {labels?.request ?? "Allow microphone"}
          </Text>
        </Pressable>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  root: { padding: 16, gap: 12, borderRadius: 16, backgroundColor: "#F3F4F6" },
  title: { color: "#15171A", fontSize: 16 },
  detail: { color: "#5D6470" },
  button: {
    minHeight: 44,
    paddingHorizontal: 16,
    alignSelf: "flex-start",
    justifyContent: "center",
    borderRadius: 12,
    backgroundColor: "#15171A",
  },
  buttonLabel: { color: "#FFFFFF", fontWeight: "600" },
});

import { useCallback, useEffect, useState } from "react";
import { Linking } from "react-native";
import { AudioModule } from "expo-audio";

export type AudioPermissionState =
  "unknown" | "requestable" | "granted" | "denied" | "blocked";

function mapPermission(permission: {
  granted: boolean;
  canAskAgain: boolean;
  status: string;
}): AudioPermissionState {
  if (permission.granted) return "granted";
  if (permission.status === "undetermined") return "requestable";
  return permission.canAskAgain ? "denied" : "blocked";
}

export function useAudioPermission() {
  const [state, setState] = useState<AudioPermissionState>("unknown");
  useEffect(() => {
    let active = true;
    void AudioModule.getRecordingPermissionsAsync().then((result) => {
      if (active) setState(mapPermission(result));
    });
    return () => {
      active = false;
    };
  }, []);

  const request = useCallback(async () => {
    const result = await AudioModule.requestRecordingPermissionsAsync();
    const next = mapPermission(result);
    setState(next);
    return next;
  }, []);

  const openSettings = useCallback(() => Linking.openSettings(), []);
  return {
    state,
    request,
    openSettings,
    refresh: async () =>
      setState(mapPermission(await AudioModule.getRecordingPermissionsAsync())),
  };
}

import { memo, type ReactNode } from "react";
import {
  StyleSheet,
  Text,
  View,
  type StyleProp,
  type ViewStyle,
} from "react-native";

export type AudioStatus =
  | "loading"
  | "buffering"
  | "ready"
  | "playing"
  | "paused"
  | "recording"
  | "interrupted"
  | "route-changed"
  | "recovering"
  | "error";
const defaults: Record<AudioStatus, string> = {
  loading: "Loading audio",
  buffering: "Buffering",
  ready: "Ready",
  playing: "Playing",
  paused: "Paused",
  recording: "Recording",
  interrupted: "Audio interrupted",
  "route-changed": "Audio route changed",
  recovering: "Recovering audio",
  error: "Audio error",
};

export const AudioStatusIndicator = memo(function AudioStatusIndicator({
  status,
  label,
  icon,
  style,
}: {
  status: AudioStatus;
  label?: string;
  icon?: ReactNode;
  style?: StyleProp<ViewStyle>;
}) {
  const text = label ?? defaults[status];
  return (
    <View
      accessible
      accessibilityRole="text"
      accessibilityLabel={text}
      accessibilityLiveRegion="polite"
      style={[styles.root, style]}
    >
      {icon}
      <View style={[styles.dot, status === "error" && styles.error]} />
      <Text style={styles.label}>{text}</Text>
    </View>
  );
});

const styles = StyleSheet.create({
  root: { minHeight: 28, flexDirection: "row", alignItems: "center", gap: 7 },
  dot: { width: 8, height: 8, borderRadius: 4, backgroundColor: "#357A57" },
  error: { backgroundColor: "#B4232F" },
  label: { color: "#454B55", fontSize: 13 },
});

import type { AgentVisualizerState } from "@siren-ui/core/recording";
import { normalizeAmplitude } from "@siren-ui/core/waveform";
import { memo, useEffect } from "react";
import { StyleSheet, View, type StyleProp, type ViewStyle } from "react-native";
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";

export type AgentVisualizerProps = {
  state: AgentVisualizerState;
  inputLevel?: number;
  outputLevel?: number;
  variant?: "orb" | "waveform-field" | "radial-bars";
  reducedMotion?: boolean;
  lowPerformanceMode?: boolean;
  accessibilityLabel?: string;
  style?: StyleProp<ViewStyle>;
};

const stateScale: Record<AgentVisualizerState, number> = {
  idle: 0.72,
  listening: 0.9,
  thinking: 0.82,
  speaking: 1,
};

export const AgentVisualizer = memo(function AgentVisualizer({
  state,
  inputLevel = 0,
  outputLevel = 0,
  variant = "orb",
  reducedMotion = false,
  lowPerformanceMode = false,
  accessibilityLabel,
  style,
}: AgentVisualizerProps) {
  const level =
    state === "speaking"
      ? normalizeAmplitude(outputLevel)
      : normalizeAmplitude(inputLevel);
  const animatedLevel = useSharedValue(level);
  const animatedState = useSharedValue(stateScale[state]);
  useEffect(() => {
    animatedLevel.value = reducedMotion
      ? level
      : withTiming(level, { duration: 90 });
    animatedState.value = reducedMotion
      ? stateScale[state]
      : withTiming(stateScale[state], { duration: 220 });
  }, [animatedLevel, animatedState, level, reducedMotion, state]);
  const orbStyle = useAnimatedStyle(() => ({
    transform: [{ scale: animatedState.value + animatedLevel.value * 0.16 }],
    opacity: 0.7 + animatedLevel.value * 0.3,
  }));
  const count = lowPerformanceMode ? 8 : variant === "orb" ? 3 : 20;
  return (
    <View
      accessible
      accessibilityRole="image"
      accessibilityLabel={accessibilityLabel ?? `Agent is ${state}`}
      style={[styles.root, style]}
    >
      {variant === "orb" ? (
        <Animated.View style={[styles.orb, orbStyle]}>
          <View style={styles.orbCore} />
