          ? 0.35
          : 0.18 + level.value * (0.4 + ((index * 7) % 11) / 16),
      },
    ],
  }));
  return (
    <Animated.View
      style={[styles.visualBar, radial && styles.radialBar, style]}
    />
  );
}

